import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_kk1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> bias,
                                 int64_t stride,
                                 int64_t padding,
                                 int64_t dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Tiled cooperative 3D convolution kernel for kernel shape (K, K, 1), groups == 1.
// Input  X: [N, C_in, A, B, E]   (PyTorch NCDHW ordering)
// Weight W: [C_out, C_in, K, K, 1]
// Output Y: [N, C_out, A_out, B_out, E_out]
//
// Because the kernel extent along the last spatial dim is 1, each (n, e) slice is an
// independent 2D convolution over (A, B). Each thread block cooperatively computes a
// (tileA x tileB) spatial tile for tileOC output channels of one (n, e) slice, staging
// the receptive input tile and the weights in shared memory via CuTe tensors.
template <typename T, int Threads>
__global__ void conv3d_kk1_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int C_in, int C_out,
    int A, int B, int E,
    int A_out, int B_out, int E_out,
    int K, int stride, int padding, int dilation,
    int tileA, int tileB, int tileOC, int chunkC,
    int tsA, int tsB,
    int aTiles, int bTiles)
{
  // Per-thread micro tile: 2x2 spatial x 8 output channels = 32 accumulators.
  constexpr int MA  = 2;
  constexpr int MB  = 2;
  constexpr int MOC = 8;

  // Decode block coordinates.
  const int ab_tiles = aTiles * bTiles;
  const int tile_ab  = blockIdx.x % ab_tiles;
  const int nz       = blockIdx.x / ab_tiles;
  const int ta       = tile_ab % aTiles;
  const int tb       = tile_ab / aTiles;
  const int n        = nz / E_out;
  const int e_out    = nz % E_out;

  const int a0  = ta * tileA;
  const int b0  = tb * tileB;
  const int oc0 = blockIdx.y * tileOC;

  // Kernel size along E is 1, so a single input slice feeds this output slice.
  const int  e_in    = e_out * stride - padding;
  const bool e_valid = (e_in >= 0) && (e_in < E);

  const int64_t sXn = (int64_t)C_in * A * B * E;
  const int64_t sXc = (int64_t)A * B * E;
  const int64_t sXa = (int64_t)B * E;
  const int64_t sXb = (int64_t)E;

  const int64_t sYn = (int64_t)C_out * A_out * B_out * E_out;
  const int64_t sYc = (int64_t)A_out * B_out * E_out;
  const int64_t sYa = (int64_t)B_out * E_out;
  const int64_t sYb = (int64_t)E_out;

  // Global CuTe tensors (per (n, e) slice views).
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn + (e_valid ? (int64_t)e_in : 0)),
                        make_shape(C_in, A, B),
                        make_stride(sXc, sXa, sXb));

  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn + (int64_t)e_out),
                        make_shape(C_out, A_out, B_out),
                        make_stride(sYc, sYa, sYb));

  const int KK = K * K;
  auto mW = make_tensor(make_gmem_ptr(Wt),
                        make_shape(C_out, C_in, KK),
                        make_stride((int64_t)C_in * KK, (int64_t)KK, Int<1>{}));

  // Dynamic shared memory staged via CuTe tensors.
  extern __shared__ __align__(16) float smem[];
  float* sX_raw = smem;
  float* sW_raw = smem + (int64_t)chunkC * tsA * tsB;

  auto sX = make_tensor(make_smem_ptr(sX_raw),
                        make_shape(chunkC, tsA, tsB),
                        make_stride((int64_t)tsA * tsB, (int64_t)tsB, Int<1>{}));
  auto sW = make_tensor(make_smem_ptr(sW_raw),
                        make_shape(tileOC, chunkC, KK),
                        make_stride((int64_t)chunkC * KK, (int64_t)KK, Int<1>{}));

  // Thread layout: 16 x 16 spatial threads x 1 output-channel group = 256 threads.
  const int tid  = threadIdx.x;
  const int ta_t = tid % 16;
  const int tb_t = (tid / 16) % 16;
  const int toc  = 0;

  // Accumulators initialized with bias (if present).
  float acc[MOC][MA][MB];
  #pragma unroll
  for (int o = 0; o < MOC; ++o) {
    const int oc = oc0 + toc * MOC + o;
    const float bv = (Bias != nullptr && oc < C_out) ? (float)Bias[oc] : 0.0f;
    #pragma unroll
    for (int i = 0; i < MA; ++i)
      #pragma unroll
      for (int j = 0; j < MB; ++j)
        acc[o][i][j] = bv;
  }

  const int la_base = ta_t * MA * stride;
  const int lb_base = tb_t * MB * stride;

  // Origin of the receptive input tile for this output tile.
  const int a_in0 = a0 * stride - padding;
  const int b_in0 = b0 * stride - padding;

  for (int c0 = 0; c0 < C_in; c0 += chunkC) {
    // Cooperative load of the weight chunk into shared memory.
    {
      const int total = tileOC * chunkC * KK;
      for (int idx = tid; idx < total; idx += Threads) {
        const int kk = idx % KK;
        const int cc = (idx / KK) % chunkC;
        const int oo = idx / (KK * chunkC);
        const int oc = oc0 + oo;
        const int ic = c0 + cc;
        float v = 0.0f;
        if (oc < C_out && ic < C_in) v = (float)mW(oc, ic, kk);
        sW(oo, cc, kk) = v;
      }
    }
    // Cooperative load of the receptive input tile into shared memory.
    {
      const int total = chunkC * tsA * tsB;
      for (int idx = tid; idx < total; idx += Threads) {
        const int bb = idx % tsB;
        const int aa = (idx / tsB) % tsA;
        const int cc = idx / (tsB * tsA);
        const int ic   = c0 + cc;
        const int a_in = a_in0 + aa;
        const int b_in = b_in0 + bb;
        float v = 0.0f;
        if (e_valid && ic < C_in &&
            a_in >= 0 && a_in < A && b_in >= 0 && b_in < B) {
          v = (float)mX(ic, a_in, b_in);
        }
        sX(cc, aa, bb) = v;
      }
    }
    __syncthreads();

    // Compute on the staged chunk.
    const int cc_max = min(chunkC, C_in - c0);
    for (int cc = 0; cc < cc_max; ++cc) {
