class ModelNew(nn.Module):
    """
    3D convolution with kernel (kernel_size, kernel_size, 1) implemented with a single
    cooperative tiled CuTe/CUDA kernel. Parameters are stored in an nn.Conv3d submodule
    so that initialization and state_dict are identical to the reference model, while
    all computation in forward() is performed by the custom CuTe kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv3d = nn.Conv3d(in_channels, out_channels,
                                (kernel_size, kernel_size, 1),
                                stride=stride, padding=padding, dilation=dilation,
                                groups=groups, bias=bias)
        self._ext = conv3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        st = self.conv3d.stride
        pd = self.conv3d.padding
        dl = self.conv3d.dilation
        if (self.conv3d.groups == 1
                and st[0] == st[1] == st[2]
                and pd[0] == pd[1] == pd[2]
                and dl[0] == dl[1] == dl[2]
                and x.is_cuda and x.dtype == torch.float32):
            return self._ext.conv3d_kk1_forward(
                x,
                self.conv3d.weight,
                self.conv3d.bias,
                int(st[0]),
                int(pd[0]),
                int(dl[0]),
            )
        # Fallback for configurations outside the custom kernel's domain.
        return self.conv3d(x)

