  for (int o = 0; o < MOC; ++o) {
    const int oc = oc0 + o;
    const float bv = (Bias != nullptr && oc < C_out) ? (float)Bias[oc] : 0.0f;
    #pragma unroll
    for (int i = 0; i < MA; ++i)
