    #pragma unroll
    for (int o = 0; o < MOC; ++o) {
      const int oc = oc0 + o;
      if (oc >= C_out) continue;
      #pragma unroll
      for (int i = 0; i < MA; ++i) {
        const int a = a0 + ta_t * MA + i;
        if (a >= A_out) continue;
