cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Tiled cooperative 3D convolution kernel for kernel shape (K, K, 1), groups == 1.
// Input  X: [N, C_in, A, B, E]   (PyTorch NCDHW ordering)
// Weight W: [C_out, C_in, K, K, 1]
// Output Y: [N, C_out, A_out, B_out, E_out]
//
// Because the kernel extent along the last spatial dim is 1, the depth (E)
// dimension is a pure batch-like, contiguous dimension. Each thread block
// cooperatively computes a (tileA x tileB x tileE) output tile for tileOC
// output channels of one batch image, staging the receptive input tile and
// the weights in shared memory via CuTe tensors. The fastest-varying threads
// are mapped to the contiguous E dimension so that all global-memory loads
// and stores are fully coalesced (the previous version mapped them to the
// strided A dimension, causing severely uncoalesced global traffic).
template <typename T, int Threads>
__global__ void conv3d_kk1_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int C_in, int C_out,
    int A, int B, int E,
    int A_out, int B_out, int E_out,
    int K, int stride, int padding, int dilation,
    int tileA, int tileB, int tileOC, int chunkC,
    int tsA, int tsB, int tileE, int tsE,
    int aTiles, int bTiles, int eTiles)
{
  // Per-thread micro tile: 2x2 spatial x 8 output channels for one depth slice.
  constexpr int MA  = 2;
  constexpr int MB  = 2;
  constexpr int MOC = 8;
  // Thread layout: 8 (A) x 4 (B) spatial threads x 8 (E) depth threads = 256.
  // E is the innermost contiguous dimension, hence the fastest thread index.
  constexpr int TA_T = 8;
  constexpr int TB_T = 4;
  constexpr int TE_T = 8;
  static_assert(Threads == TA_T * TB_T * TE_T, "thread layout mismatch");
  // Decode block coordinates.
  const int ab_tiles = aTiles * bTiles;
  const int tile_ab  = blockIdx.x % ab_tiles;
  const int nz       = blockIdx.x / ab_tiles;
  const int ta       = tile_ab % aTiles;
  const int tb       = tile_ab / aTiles;
  const int n        = nz / eTiles;
  const int te_blk   = nz % eTiles;
  const int a0  = ta * tileA;
  const int b0  = tb * tileB;
  const int e0  = te_blk * tileE;
  const int oc0 = blockIdx.y * tileOC;
  const int64_t sXn = (int64_t)C_in * A * B * E;
  const int64_t sXc = (int64_t)A * B * E;
  const int64_t sXa = (int64_t)B * E;
  const int64_t sXb = (int64_t)E;
  const int64_t sYn = (int64_t)C_out * A_out * B_out * E_out;
  const int64_t sYc = (int64_t)A_out * B_out * E_out;
  const int64_t sYa = (int64_t)B_out * E_out;
  const int64_t sYb = (int64_t)E_out;
  // Global CuTe tensors, exposing the contiguous depth dimension.
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                        make_shape(C_in, A, B, E),
                        make_stride(sXc, sXa, sXb, Int<1>{}));
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                        make_shape(C_out, A_out, B_out, E_out),
                        make_stride(sYc, sYa, sYb, Int<1>{}));
  const int KK = K * K;
  auto mW = make_tensor(make_gmem_ptr(Wt),
                        make_shape(C_out, C_in, KK),
                        make_stride((int64_t)C_in * KK, (int64_t)KK, Int<1>{}));
  // Dynamic shared memory staged via CuTe tensors. The depth stride of the
  // staged input tile is padded to an odd value to keep the per-thread
  // depth lanes on distinct shared-memory banks.
  const int tsE_smem = tsE + ((tsE % 2 == 0) ? 1 : 0);
  extern __shared__ __align__(16) float smem[];
  float* sX_raw = smem;
  float* sW_raw = smem + (int64_t)chunkC * tsA * tsB * tsE_smem;
  auto sX = make_tensor(make_smem_ptr(sX_raw),
                        make_shape(chunkC, tsA, tsB, tsE),
                        make_stride((int64_t)tsA * tsB * tsE_smem,
                                    (int64_t)tsB * tsE_smem,
                                    (int64_t)tsE_smem, Int<1>{}));
  auto sW = make_tensor(make_smem_ptr(sW_raw),
                        make_shape(tileOC, chunkC, KK),
                        make_stride((int64_t)chunkC * KK, (int64_t)KK, Int<1>{}));
  const int tid  = threadIdx.x;
  const int te_t = tid % TE_T;
  const int tb_t = (tid / TE_T) % TB_T;
  const int ta_t = tid / (TE_T * TB_T);
  // Accumulators initialized with bias (if present).
  float acc[MOC][MA][MB];
  #pragma unroll
  for (int o = 0; o < MOC; ++o) {
    const int oc = oc0 + o;
    const float bv = (Bias != nullptr && oc < C_out) ? (float)Bias[oc] : 0.0f;
    #pragma unroll
    for (int i = 0; i < MA; ++i)
      #pragma unroll
      for (int j = 0; j < MB; ++j)
        acc[o][i][j] = bv;
  }
  const int la_base = ta_t * MA * stride;
  const int lb_base = tb_t * MB * stride;
  const int le_base = te_t * stride;
  // Origins of the receptive input tile for this output tile.
  const int a_in0 = a0 * stride - padding;
  const int b_in0 = b0 * stride - padding;
  const int e_in0 = e0 * stride - padding;
  for (int c0 = 0; c0 < C_in; c0 += chunkC) {
    // Cooperative load of the weight chunk into shared memory.
    {
      const int total = tileOC * chunkC * KK;
      for (int idx = tid; idx < total; idx += Threads) {
        const int kk = idx % KK;
        const int cc = (idx / KK) % chunkC;
        const int oo = idx / (KK * chunkC);
        const int oc = oc0 + oo;
        const int ic = c0 + cc;
        float v = 0.0f;
        if (oc < C_out && ic < C_in) v = (float)mW(oc, ic, kk);
        sW(oo, cc, kk) = v;
      }
    }
    // Cooperative load of the receptive input tile into shared memory.
    // Depth is the fastest-varying index, so global reads are coalesced.
    {
      const int total = chunkC * tsA * tsB * tsE;
      for (int idx = tid; idx < total; idx += Threads) {
        const int ee = idx % tsE;
        const int bb = (idx / tsE) % tsB;
        const int aa = (idx / (tsE * tsB)) % tsA;
        const int cc = idx / (tsE * tsB * tsA);
        const int ic   = c0 + cc;
        const int a_in = a_in0 + aa;
        const int b_in = b_in0 + bb;
        const int e_in = e_in0 + ee;
        float v = 0.0f;
        if (ic < C_in &&
            a_in >= 0 && a_in < A &&
            b_in >= 0 && b_in < B &&
            e_in >= 0 && e_in < E) {
          v = (float)mX(ic, a_in, b_in, e_in);
        }
        sX(cc, aa, bb, ee) = v;
      }
    }
    __syncthreads();
    // Compute on the staged chunk.
    const int cc_max = min(chunkC, C_in - c0);
    for (int cc = 0; cc < cc_max; ++cc) {
      for (int ka = 0; ka < K; ++ka) {
        const int la_k = ka * dilation;
        for (int kb = 0; kb < K; ++kb) {
          const int lb_k = kb * dilation;
          float xv[MA][MB];
          #pragma unroll
          for (int i = 0; i < MA; ++i) {
            const int la = la_base + i * stride + la_k;
            #pragma unroll
            for (int j = 0; j < MB; ++j) {
              const int lb = lb_base + j * stride + lb_k;
              xv[i][j] = sX(cc, la, lb, le_base);
            }
          }
          float wv[MOC];
          #pragma unroll
          for (int o = 0; o < MOC; ++o)
            wv[o] = sW(o, cc, ka * K + kb);
          #pragma unroll
          for (int o = 0; o < MOC; ++o)
            #pragma unroll
            for (int i = 0; i < MA; ++i)
              #pragma unroll
              for (int j = 0; j < MB; ++j)
                acc[o][i][j] += xv[i][j] * wv[o];
        }
      }
    }
    __syncthreads();
  }
  // Epilogue: guarded store of the output tile. Consecutive threads write
  // consecutive depth positions, so global stores are coalesced.
  const int e_out = e0 + te_t;
  if (e_out < E_out) {
    #pragma unroll
    for (int o = 0; o < MOC; ++o) {
      const int oc = oc0 + o;
      if (oc >= C_out) continue;
      #pragma unroll
      for (int i = 0; i < MA; ++i) {
        const int a = a0 + ta_t * MA + i;
        if (a >= A_out) continue;
        #pragma unroll
        for (int j = 0; j < MB; ++j) {
          const int b = b0 + tb_t * MB + j;
          if (b >= B_out) continue;
          mY(oc, a, b, e_out) = (T)acc[o][i][j];
        }
      }
    }
  }
}

torch::Tensor conv3d_kk1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> bias,
                                 int64_t stride,
                                 int64_t padding,
                                 int64_t dilation) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be 5D [N, C_in, A, B, E]");
  TORCH_CHECK(w.dim() == 5, "w must be 5D [C_out, C_in, K, K, 1]");
  TORCH_CHECK(stride >= 1 && dilation >= 1 && padding >= 0,
              "invalid stride/padding/dilation");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N    = x_c.size(0);
  const int64_t C_in = x_c.size(1);
  const int64_t A    = x_c.size(2);
  const int64_t B    = x_c.size(3);
  const int64_t E    = x_c.size(4);

  const int64_t C_out = w_c.size(0);
  TORCH_CHECK(w_c.size(1) == C_in, "groups must be 1 (w.size(1) == C_in)");
  const int64_t K = w_c.size(2);
  TORCH_CHECK(w_c.size(3) == K && w_c.size(4) == 1, "kernel must be (K, K, 1)");
  TORCH_CHECK(K >= 1, "kernel size must be >= 1");

  const float* bias_ptr = nullptr;
  torch::Tensor b_c;
  if (bias.has_value() && bias->defined()) {
    b_c = bias->contiguous();
    TORCH_CHECK(b_c.scalar_type() == at::kFloat && b_c.dim() == 1 && b_c.size(0) == C_out,
                "bias must be float32 of shape [C_out]");
    bias_ptr = b_c.data_ptr<float>();
  }

  const int64_t A_out = (A + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  const int64_t B_out = (B + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  const int64_t E_out = (E + 2 * padding - 1) / stride + 1;  // kernel extent 1 on E
  TORCH_CHECK(A_out > 0 && B_out > 0 && E_out > 0, "invalid output size");

  auto y = torch::empty({N, C_out, A_out, B_out, E_out}, x_c.options());

  constexpr int Threads = 256;
  constexpr int tileA   = 16;   // 8 threads  x 2 outputs
  constexpr int tileB   = 8;    // 4 threads  x 2 outputs
  constexpr int tileOC  = 8;    // 8 output channels per block
  constexpr int chunkC  = 4;
  constexpr int tileE   = 8;    // 8 depth threads (contiguous, coalesced)
  const int64_t tsA = (tileA - 1) * stride + dilation * (K - 1) + 1;
  const int64_t tsB = (tileB - 1) * stride + dilation * (K - 1) + 1;
  const int64_t tsE = (tileE - 1) * stride + 1;  // kernel extent 1 on E
  const int64_t tsE_smem = tsE + ((tsE % 2 == 0) ? 1 : 0);
  const int64_t aTiles  = (A_out + tileA - 1) / tileA;
  const int64_t bTiles  = (B_out + tileB - 1) / tileB;
  const int64_t eTiles  = (E_out + tileE - 1) / tileE;
  const int64_t ocTiles = (C_out + tileOC - 1) / tileOC;
  TORCH_CHECK(ocTiles <= 65535, "too many output-channel tiles");
  const int64_t smem_floats = (int64_t)chunkC * tsA * tsB * tsE_smem
                            + (int64_t)tileOC * chunkC * K * K;
  const int64_t smem_bytes  = smem_floats * (int64_t)sizeof(float);
  TORCH_CHECK(smem_bytes <= 200 * 1024, "shared memory requirement too large");
  auto kernel = conv3d_kk1_tiled_kernel<float, Threads>;
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
  }
  dim3 block(Threads);
  dim3 grid((unsigned)(aTiles * bTiles * eTiles * N), (unsigned)ocTiles, 1);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  kernel<<<grid, block, (size_t)smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      bias_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C_in, (int)C_out,
      (int)A, (int)B, (int)E,
      (int)A_out, (int)B_out, (int)E_out,
      (int)K, (int)stride, (int)padding, (int)dilation,
      tileA, tileB, tileOC, chunkC,
      (int)tsA, (int)tsB, tileE, (int)tsE,
      (int)aTiles, (int)bTiles, (int)eTiles);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kk1_tiled_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
